{
  "name": "BioShake微孔板加热振荡器",
  "name_en": "BioShake microplate heater shaker",
  "manufacturer": "",
  "description": "BioShake是一种用于微孔板样品处理的台式加热振荡设备，可对板内样品进行控温与振荡混匀，并支持夹板锁定。常用于分子生物学与生化实验中的孵育、溶解、反应混合和样品预处理。",
  "description_en": "BioShake is a benchtop microplate heater shaker for temperature-controlled incubation and shaking/mixing of plate-based samples, with plate locking support. It is commonly used in molecular biology and biochemistry workflows for incubation, dissolution, reaction mixing, and sample preparation.",
  "actions": [
    {
      "action_name": "auto-deactivate",
      "description": "关闭温度控制。",
      "description_en": "Deactivate temperature control."
    },
    {
      "action_name": "auto-home",
      "description": "使设备回到初始原点位置。",
      "description_en": "Home the device to its initial reference position."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定微孔板。",
      "description_en": "Lock the microplate."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备以清除错误或卡滞状态。",
      "description_en": "Reset the device to clear error or stuck states."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设定并启动目标温度控制。",
      "description_en": "Set and start temperature control to the target temperature."
    },
    {
      "action_name": "auto-setup",
      "description": "执行初始化准备（复位并回零）。",
      "description_en": "Run setup initialization (reset and home)."
    },
    {
      "action_name": "auto-shake",
      "description": "按设定转速（及加速度）开始振荡混匀。",
      "description_en": "Start shaking/mixing at the set speed (and acceleration)."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备当前运行。",
      "description_en": "Stop current device operation."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "按设定减速度停止振荡。",
      "description_en": "Stop shaking with the specified deceleration."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁微孔板。",
      "description_en": "Unlock the microplate."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取是否支持锁板功能。",
      "description_en": "Get whether plate locking is supported."
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取是否支持主动制冷功能。",
      "description_en": "Get whether active cooling is supported."
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    }
  ],
  "tag_hints": [
    "microplate heating and shaking",
    "orbital mixing",
    "temperature control",
    "plate locking/clamping",
    "sample incubation",
    "lab automation"
  ]
}
